using System;using System.Drawing;using System.Windows.Forms;using IslandIntegrated;
class VisualChecks {[STAThread]static int Main(){if(CornerLayout.Width!=360||CornerLayout.CompactHeight!=80||CornerLayout.Gap!=24)throw new Exception("corner geometry");if(WidgetGrid.SmallWidth(360)!=168||WidgetGrid.Gap!=24)throw new Exception("grid geometry");var cc=StatusUiLayout.CcSwitchButton(360,true);var close=StatusDockState.CollapseButton(360);if(close.Left-cc.Right!=6)throw new Exception("button gap");using(var picker=new ThemePicker()){if(picker.Width!=216||picker.Height!=240||picker.Items.Count!=7)throw new Exception("menu geometry");picker.CurrentTheme="iris";if(!((ToolStripMenuItem)picker.Items[3]).Checked)throw new Exception("menu check");string selected=null;picker.Selected+=(s,e)=>selected=e.Theme;((ToolStripMenuItem)picker.Items[4]).PerformClick();if(selected!="amber")throw new Exception("menu select");}Console.WriteLine("PASS 360/80/24 geometry, 168 small card, original compact button spacing and theme menu selection");return 0;}}
